//! ECDSA P-256 keys for SSH (ADR-0010): the agent keys and those of
//! `ostena login` are generated by `ostena-crypto` (aws-lc-rs), never by the
//! SSH library or by `rand`, and written in the OpenSSH private key format.
//!
//! **The scalar always takes 32 bytes.** OpenSSH writes it as a minimal
//! `mpint`, so a scalar whose first byte is zero takes
//! 31 bytes when its second byte is below 0x80 too (about one key in 512), which
//! `ssh-key 0.7.0-rc.11` refuses. A literal 32-byte `mpint`
//! with a superfluous leading zero would not be canonical either, and OpenSSH
//! refuses those. Such scalars are therefore drawn again: the key loses less
//! than 0.006 bit of its 256.
//!
//! A key imported by an administrator and hit by the defect is refused with
//! an explicit message (`SSH-E007`), rather than a parsing error.

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use ostena_common::secret::SecretBytes;
use ostena_crypto::p256::{SigningKey, VerifyingKey};

const MAGIC: &[u8] = b"openssh-key-v1\0";
const KEY_TYPE: &str = "ecdsa-sha2-nistp256";
const CURVE: &str = "nistp256";
const BEGIN: &str = "-----BEGIN OPENSSH PRIVATE KEY-----";
const END: &str = "-----END OPENSSH PRIVATE KEY-----";
/// Largest private key file read (a P-256 key is about 500 bytes).
const MAX_KEY_FILE: usize = 16 * 1024;

/// Why a key cannot be made or used. Codes are stable.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum KeyError {
    /// The scalar is encoded on fewer than 32 bytes: the SSH library refuses
    /// it (upstream defect, ADR-0010).
    #[error(
        "[SSH-E007] clé P-256 refusée : son scalaire privé est encodé sur {0} octets au lieu de 32 \
         (environ une clé sur 512 produite par ssh-keygen). La bibliothèque SSH ne sait pas la \
         lire ; générez-en une nouvelle, ou laissez Ostena générer la clé"
    )]
    ShortScalar(usize),
    /// Not an unencrypted OpenSSH ECDSA P-256 private key.
    #[error("[SSH-E008] clé privée SSH invalide : {0}")]
    Invalid(String),
    /// Generation failed.
    #[error("[SSH-E009] génération de la clé impossible : {0}")]
    Generation(String),
}

impl KeyError {
    /// The stable code.
    pub fn code(&self) -> &'static str {
        match self {
            Self::ShortScalar(_) => "SSH-E007",
            Self::Invalid(_) => "SSH-E008",
            Self::Generation(_) => "SSH-E009",
        }
    }
}

/// A generated key: the private key file (secret) and the public key line.
pub struct GeneratedKey {
    /// OpenSSH private key file, unencrypted (to be stored with private
    /// rights).
    pub private: SecretBytes,
    /// `ecdsa-sha2-nistp256 AAAA… comment`.
    pub public: String,
}

impl std::fmt::Debug for GeneratedKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("GeneratedKey")
            .field("public", &self.public)
            .finish_non_exhaustive()
    }
}

fn put_u32(out: &mut Vec<u8>, value: usize) {
    out.extend_from_slice(&u32::try_from(value).unwrap_or(u32::MAX).to_be_bytes());
}

fn put_string(out: &mut Vec<u8>, bytes: &[u8]) {
    put_u32(out, bytes.len());
    out.extend_from_slice(bytes);
}

/// A minimal `mpint` (RFC 4251 §5) of a positive big-endian integer.
fn put_mpint(out: &mut Vec<u8>, value: &[u8]) {
    let start = value.iter().position(|&b| b != 0).unwrap_or(value.len());
    let digits = &value[start..];
    let pad = digits.first().is_some_and(|b| b & 0x80 != 0);
    put_u32(out, digits.len() + usize::from(pad));
    if pad {
        out.push(0);
    }
    out.extend_from_slice(digits);
}

fn public_blob(public: &[u8; 65]) -> Vec<u8> {
    let mut blob = Vec::with_capacity(104);
    put_string(&mut blob, KEY_TYPE.as_bytes());
    put_string(&mut blob, CURVE.as_bytes());
    put_string(&mut blob, public);
    blob
}

/// The OpenSSH public key line of `key`: `ecdsa-sha2-nistp256 AAAA…`,
/// followed by ` comment` when `comment` is not empty.
pub fn public_line(key: &VerifyingKey, comment: &str) -> String {
    let encoded = STANDARD.encode(public_blob(&key.to_bytes()));
    if comment.is_empty() {
        format!("{KEY_TYPE} {encoded}")
    } else {
        format!("{KEY_TYPE} {encoded} {comment}")
    }
}

/// The key of an OpenSSH public key line `ecdsa-sha2-nistp256 AAAA…
/// [comment]` (an `ssh_host_ecdsa_key.pub` file), if it is one: of the
/// frozen type, its blob canonical, its point on the curve.
pub fn parse_public_line(line: &str) -> Option<VerifyingKey> {
    let mut fields = line.split_ascii_whitespace();
    if fields.next()? != KEY_TYPE {
        return None;
    }
    let blob = STANDARD.decode(fields.next()?).ok()?;
    let point: [u8; 65] = blob.get(blob.len().checked_sub(65)?..)?.try_into().ok()?;
    if public_blob(&point) != blob {
        return None;
    }
    VerifyingKey::from_bytes(&point).ok()
}

/// Writes `key` in the OpenSSH private key format, unencrypted, with its
/// scalar as a minimal `mpint`.
///
/// # Errors
///
/// [`KeyError::Generation`] if the scalar cannot be exported or the random
/// check value drawn.
pub fn encode(key: &SigningKey, comment: &str) -> Result<GeneratedKey, KeyError> {
    let failed = |e: ostena_crypto::CryptoError| KeyError::Generation(e.to_string());
    let public = key.verifying_key().to_bytes();
    let blob = public_blob(&public);
    let scalar = key.scalar().map_err(failed)?;
    let check = ostena_crypto::rand::array::<4>().map_err(failed)?;

    let mut private = Vec::with_capacity(200);
    private.extend_from_slice(&check);
    private.extend_from_slice(&check);
    put_string(&mut private, KEY_TYPE.as_bytes());
    put_string(&mut private, CURVE.as_bytes());
    put_string(&mut private, &public);
    // SECRET-EXPOSURE: the scalar is written once into the private section,
    // which becomes a secret right below.
    #[expect(clippy::disallowed_methods)]
    put_mpint(&mut private, scalar.expose_secret());
    put_string(&mut private, comment.as_bytes());
    let mut pad = 1u8;
    while private.len() % 8 != 0 {
        private.push(pad);
        pad += 1;
    }
    let private = SecretBytes::from(private);

    let mut body = MAGIC.to_vec();
    put_string(&mut body, b"none");
    put_string(&mut body, b"none");
    put_string(&mut body, b"");
    put_u32(&mut body, 1);
    put_string(&mut body, &blob);
    // SECRET-EXPOSURE: assembled into the file body, itself a secret.
    #[expect(clippy::disallowed_methods)]
    put_string(&mut body, private.expose_secret());
    let body = SecretBytes::from(body);

    // SECRET-EXPOSURE: base64 of the secret body, kept as a secret.
    #[expect(clippy::disallowed_methods)]
    let encoded = SecretBytes::from(STANDARD.encode(body.expose_secret()).into_bytes());
    let mut file = Vec::with_capacity(600);
    file.extend_from_slice(BEGIN.as_bytes());
    file.push(b'\n');
    // SECRET-EXPOSURE: wrapped into the file, kept as a secret.
    #[expect(clippy::disallowed_methods)]
    for line in encoded.expose_secret().chunks(70) {
        file.extend_from_slice(line);
        file.push(b'\n');
    }
    file.extend_from_slice(END.as_bytes());
    file.push(b'\n');
    Ok(GeneratedKey {
        private: SecretBytes::from(file),
        public: format!("{KEY_TYPE} {} {comment}", STANDARD.encode(&blob)),
    })
}

/// Generates an ECDSA P-256 key with `ostena-crypto`, its scalar on 32
/// bytes, and writes it in the OpenSSH format.
///
/// # Errors
///
/// [`KeyError::Generation`].
pub fn generate(comment: &str) -> Result<GeneratedKey, KeyError> {
    let failed = |e: ostena_crypto::CryptoError| KeyError::Generation(e.to_string());
    // A first byte of zero has a probability of 1/256: 64 draws never fail
    // in practice.
    for _ in 0..64 {
        let (key, _) = SigningKey::generate().map_err(failed)?;
        // SECRET-EXPOSURE: only the first byte is looked at.
        #[expect(clippy::disallowed_methods)]
        let full_width = key.scalar().map_err(failed)?.expose_secret()[0] != 0;
        if full_width {
            return encode(&key, comment);
        }
    }
    Err(KeyError::Generation(
        "aucun scalaire de 32 octets en 64 tirages".into(),
    ))
}

/// One SSH `string` field, borrowed: nothing of a secret is copied.
fn take<'a>(rest: &mut &'a [u8]) -> Option<&'a [u8]> {
    let len = u32::from_be_bytes(rest.get(..4)?.try_into().ok()?) as usize;
    let value = rest.get(4..4usize.checked_add(len)?)?;
    *rest = &rest[4 + len..];
    Some(value)
}

/// Length of the `mpint` holding the private scalar of an unencrypted OpenSSH
/// ECDSA P-256 key file, as encoded; `None` if the file is not one.
/// Bounded, never panics: used to explain a refusal.
pub fn scalar_len(file: &[u8]) -> Option<usize> {
    let body = decode_body(file)?;
    // SECRET-EXPOSURE: walked to read one length, never copied.
    #[expect(clippy::disallowed_methods)]
    private_section(body.expose_secret()).map(|s| s.scalar.len())
}

/// The fields of the private section of an unencrypted OpenSSH ECDSA P-256
/// key file, borrowed from the decoded body.
struct PrivateSection<'a> {
    public: &'a [u8],
    scalar: &'a [u8],
    comment: &'a [u8],
}

/// The decoded body of an OpenSSH private key file. Bounded.
fn decode_body(file: &[u8]) -> Option<SecretBytes> {
    if file.len() > MAX_KEY_FILE {
        return None;
    }
    let text = std::str::from_utf8(file).ok()?;
    let inner = text.trim().strip_prefix(BEGIN)?.strip_suffix(END)?;
    let compact: String = inner.chars().filter(|c| !c.is_whitespace()).collect();
    Some(SecretBytes::from(STANDARD.decode(compact).ok()?))
}

/// Walks a decoded body. Never panics.
fn private_section(body: &[u8]) -> Option<PrivateSection<'_>> {
    let mut rest = body.strip_prefix(MAGIC)?;
    if take(&mut rest)? != b"none" || take(&mut rest)? != b"none" {
        return None;
    }
    take(&mut rest)?; // KDF options
    let count = rest.get(..4)?;
    if count != [0, 0, 0, 1] {
        return None;
    }
    rest = &rest[4..];
    take(&mut rest)?; // public key
    let private = take(&mut rest)?;
    let check = private.get(..8)?;
    if check[..4] != check[4..] {
        return None;
    }
    let mut section: &[u8] = &private[8..];
    if take(&mut section)? != KEY_TYPE.as_bytes() || take(&mut section)? != CURVE.as_bytes() {
        return None;
    }
    let public = take(&mut section)?;
    let scalar = take(&mut section)?;
    let comment = take(&mut section)?;
    Some(PrivateSection {
        public,
        scalar,
        comment,
    })
}

/// Reads an unencrypted OpenSSH ECDSA P-256 private key file for
/// `ostena-crypto` (proofs of possession): the signing key and the comment
/// of the file. The scalar may take 31 to 33 bytes (minimal `mpint`); the
/// public point of the file must be the one of the scalar.
///
/// # Errors
///
/// [`KeyError::Invalid`].
pub fn decode(file: &SecretBytes) -> Result<(SigningKey, String), KeyError> {
    let invalid = |what: &str| KeyError::Invalid(what.to_owned());
    let unexpected = "fichier de clé OpenSSH ECDSA P-256 non chiffrée attendu";
    // SECRET-EXPOSURE: decoded into a secret.
    #[expect(clippy::disallowed_methods)]
    let body = decode_body(file.expose_secret()).ok_or_else(|| invalid(unexpected))?;
    // SECRET-EXPOSURE: walked; the scalar is only copied into a secret.
    #[expect(clippy::disallowed_methods)]
    let section = private_section(body.expose_secret()).ok_or_else(|| invalid(unexpected))?;
    // A minimal mpint: one leading zero only before a high bit.
    let digits = match section.scalar {
        [0, next, ..] if next & 0x80 != 0 => &section.scalar[1..],
        [0, ..] | [] => return Err(invalid("scalaire privé mal encodé")),
        _ => section.scalar,
    };
    if digits.len() > 32 {
        return Err(invalid("scalaire privé mal encodé"));
    }
    // Allocated once at its final size: no copy left behind by a growth.
    let mut scalar = Vec::with_capacity(32);
    scalar.resize(32 - digits.len(), 0);
    scalar.extend_from_slice(digits);
    let key = SigningKey::from_scalar(&SecretBytes::from(scalar))
        .map_err(|e| KeyError::Invalid(e.to_string()))?;
    if key.verifying_key().to_bytes()[..] != *section.public {
        return Err(invalid(
            "la clé publique du fichier ne correspond pas à son scalaire",
        ));
    }
    Ok((key, String::from_utf8_lossy(section.comment).into_owned()))
}

/// Loads an unencrypted OpenSSH ECDSA P-256 private key for the SSH
/// library.
///
/// # Errors
///
/// [`KeyError::ShortScalar`] for a key hit by the upstream defect,
/// [`KeyError::Invalid`] otherwise.
#[cfg(feature = "russh")]
pub fn load(file: &SecretBytes) -> Result<russh::keys::PrivateKey, KeyError> {
    use russh::keys::{Algorithm, EcdsaCurve};

    // SECRET-EXPOSURE: parsed by the SSH library.
    #[expect(clippy::disallowed_methods)]
    let bytes = file.expose_secret();
    match russh::keys::PrivateKey::from_openssh(bytes) {
        Ok(key)
            if key.algorithm()
                == Algorithm::Ecdsa {
                    curve: EcdsaCurve::NistP256,
                } =>
        {
            Ok(key)
        }
        Ok(key) => Err(KeyError::Invalid(format!(
            "algorithme {} hors de la liste figée (ecdsa-sha2-nistp256)",
            key.algorithm()
        ))),
        Err(e) => match scalar_len(bytes) {
            Some(len) if len < 32 => Err(KeyError::ShortScalar(len)),
            _ => Err(KeyError::Invalid(e.to_string())),
        },
    }
}

